-- Preserve original purchases and authorize only prices explicitly selected for
-- this subscription. Change invoices freeze their own grant evidence.
CREATE TABLE subscription_plan_prices(subscription_id TEXT NOT NULL REFERENCES subscriptions(id),price_id TEXT NOT NULL,plan_id TEXT NOT NULL,billing_interval TEXT NOT NULL CHECK(billing_interval IN('month','year')),amount_cents INTEGER NOT NULL CHECK(amount_cents>0),monthly_credits INTEGER NOT NULL CHECK(monthly_credits>0),created_at INTEGER NOT NULL DEFAULT(unixepoch()),PRIMARY KEY(subscription_id,price_id));
CREATE TABLE subscription_change_invoices(id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL REFERENCES subscriptions(id),user_id TEXT NOT NULL REFERENCES users(id),provider_mode TEXT NOT NULL CHECK(provider_mode IN('test','live')),invoice_id TEXT NOT NULL,period_start INTEGER NOT NULL,period_end INTEGER NOT NULL CHECK(period_end>period_start),from_price_id TEXT NOT NULL,to_price_id TEXT NOT NULL,from_monthly_credits INTEGER NOT NULL CHECK(from_monthly_credits>0),to_monthly_credits INTEGER NOT NULL CHECK(to_monthly_credits>0),billing_interval TEXT NOT NULL CHECK(billing_interval IN('month','year')),reset_period INTEGER NOT NULL CHECK(reset_period IN(0,1)),created_at INTEGER NOT NULL DEFAULT(unixepoch()),UNIQUE(provider_mode,invoice_id));
ALTER TABLE subscriptions ADD COLUMN credit_reset_at INTEGER NOT NULL DEFAULT 0;
-- Rebuild instead of renaming the old tables: existing allocation foreign keys
-- keep their stable table names and every historical row ID remains unchanged.
PRAGMA defer_foreign_keys=ON;
DROP TRIGGER generation_charge;
DROP TRIGGER ledger_apply;
CREATE TABLE subscription_invoices_next(id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL REFERENCES subscriptions(id),user_id TEXT NOT NULL REFERENCES users(id),provider_mode TEXT NOT NULL CHECK(provider_mode IN('test','live')),invoice_id TEXT NOT NULL,period_start INTEGER NOT NULL,period_end INTEGER NOT NULL CHECK(period_end>period_start),billing_interval TEXT NOT NULL CHECK(billing_interval IN('month','year')),monthly_credits INTEGER NOT NULL CHECK(monthly_credits>0),created_at INTEGER NOT NULL DEFAULT(unixepoch()),price_id TEXT NOT NULL DEFAULT '',UNIQUE(provider_mode,invoice_id),UNIQUE(subscription_id,period_start,price_id));
INSERT INTO subscription_invoices_next(id,subscription_id,user_id,provider_mode,invoice_id,period_start,period_end,billing_interval,monthly_credits,created_at,price_id) SELECT i.id,i.subscription_id,i.user_id,i.provider_mode,i.invoice_id,i.period_start,i.period_end,i.billing_interval,i.monthly_credits,i.created_at,s.price_id FROM subscription_invoices i JOIN subscriptions s ON s.id=i.subscription_id;
CREATE TABLE subscription_credit_periods_next(id TEXT PRIMARY KEY,invoice_id TEXT NOT NULL REFERENCES subscription_invoices(id),subscription_id TEXT NOT NULL REFERENCES subscriptions(id),user_id TEXT NOT NULL REFERENCES users(id),starts_at INTEGER NOT NULL,ends_at INTEGER NOT NULL CHECK(ends_at>starts_at),granted INTEGER NOT NULL CHECK(granted>0),remaining INTEGER NOT NULL CHECK(remaining>=0 AND remaining<=granted),retired_at INTEGER,UNIQUE(invoice_id,starts_at));
INSERT INTO subscription_credit_periods_next(id,invoice_id,subscription_id,user_id,starts_at,ends_at,granted,remaining) SELECT id,invoice_id,subscription_id,user_id,starts_at,ends_at,granted,remaining FROM subscription_credit_periods;
DROP TABLE subscription_credit_periods;
DROP TABLE subscription_invoices;
ALTER TABLE subscription_invoices_next RENAME TO subscription_invoices;
ALTER TABLE subscription_credit_periods_next RENAME TO subscription_credit_periods;
CREATE INDEX subscription_credit_available ON subscription_credit_periods(user_id,starts_at,ends_at);
-- During rollout the previous Worker still omits price_id. Resolve its
-- original purchase in the same insert transaction; uniqueness is enforced
-- again on the update, so another invoice cannot replenish that paid period.
CREATE TRIGGER subscription_invoice_original_price AFTER INSERT ON subscription_invoices WHEN NEW.price_id='' BEGIN UPDATE subscription_invoices SET price_id=(SELECT price_id FROM subscriptions WHERE id=NEW.subscription_id) WHERE id=NEW.id; END;
-- Refunds retain their historical bucket; retired buckets cannot be spent.
CREATE TRIGGER ledger_apply AFTER INSERT ON credit_ledger BEGIN  UPDATE users SET credits=credits+(CASE WHEN NEW.kind='subscription_grant' THEN 0 WHEN NEW.kind IN('generation','refund') AND EXISTS(SELECT 1 FROM generation_credit_allocations WHERE generation_id=NEW.reference_id) THEN (CASE WHEN NEW.kind='generation' THEN -1 ELSE 1 END)*(SELECT permanent_amount FROM generation_credit_allocations WHERE generation_id=NEW.reference_id) ELSE NEW.amount END) WHERE id=NEW.user_id;  UPDATE subscription_credit_periods SET remaining=remaining+(SELECT amount FROM generation_subscription_allocations WHERE generation_id=NEW.reference_id AND period_id=subscription_credit_periods.id) WHERE NEW.kind='refund' AND id IN(SELECT period_id FROM generation_subscription_allocations WHERE generation_id=NEW.reference_id); END;
CREATE TRIGGER generation_charge AFTER INSERT ON generations BEGIN  SELECT CASE WHEN NEW.cost>(SELECT credits FROM users WHERE id=NEW.user_id)+COALESCE((SELECT SUM(remaining) FROM subscription_credit_periods WHERE user_id=NEW.user_id AND retired_at IS NULL AND starts_at<=unixepoch() AND ends_at>unixepoch()),0) THEN RAISE(ABORT,'insufficient_credits') END;  INSERT INTO generation_credit_allocations(generation_id,permanent_amount) VALUES(NEW.id,MAX(0,NEW.cost-COALESCE((SELECT SUM(remaining) FROM subscription_credit_periods WHERE user_id=NEW.user_id AND retired_at IS NULL AND starts_at<=unixepoch() AND ends_at>unixepoch()),0)));  INSERT INTO generation_subscription_allocations(generation_id,period_id,amount) SELECT NEW.id,p.id,MIN(p.remaining,MAX(0,NEW.cost-COALESCE((SELECT SUM(q.remaining) FROM subscription_credit_periods q WHERE q.user_id=NEW.user_id AND q.retired_at IS NULL AND q.starts_at<=unixepoch() AND q.ends_at>unixepoch() AND (q.ends_at,q.starts_at,q.id)<(p.ends_at,p.starts_at,p.id)),0))) FROM subscription_credit_periods p WHERE p.user_id=NEW.user_id AND p.retired_at IS NULL AND p.starts_at<=unixepoch() AND p.ends_at>unixepoch() AND p.remaining>0 AND NEW.cost>COALESCE((SELECT SUM(q.remaining) FROM subscription_credit_periods q WHERE q.user_id=NEW.user_id AND q.retired_at IS NULL AND q.starts_at<=unixepoch() AND q.ends_at>unixepoch() AND (q.ends_at,q.starts_at,q.id)<(p.ends_at,p.starts_at,p.id)),0);  UPDATE subscription_credit_periods SET remaining=remaining-(SELECT amount FROM generation_subscription_allocations WHERE generation_id=NEW.id AND period_id=subscription_credit_periods.id) WHERE id IN(SELECT period_id FROM generation_subscription_allocations WHERE generation_id=NEW.id);  INSERT INTO credit_ledger(id,user_id,amount,kind,reference_id) VALUES(NEW.id||':debit',NEW.user_id,-NEW.cost,'generation',NEW.id); END;
PRAGMA defer_foreign_keys=OFF;
